/// 一种传输协议（http_stream / http_hls）。
class LiveStream {
  final String? protocolName;
  final List<LiveFormat> format;

  const LiveStream({
    this.protocolName,
    required this.format,
  });

  @override
  int get hashCode => protocolName.hashCode ^ format.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is LiveStream &&
          runtimeType == other.runtimeType &&
          protocolName == other.protocolName &&
          format == other.format;
}

/// 一个 CDN 节点。拼流地址时 `host + base_url + extra` 三段相连。
class LiveUrlInfo {
  final String host;
  final String extra;

  const LiveUrlInfo({
    required this.host,
    required this.extra,
  });

  @override
  int get hashCode => host.hashCode ^ extra.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is LiveUrlInfo &&
          runtimeType == other.runtimeType &&
          host == other.host &&
          extra == other.extra;
}
